// These headers are used by code generated at runtime in KERNEL_SPECS blocks
#include <torch/csrc/stable/accelerator.h>
#include <torch/csrc/stable/macros.h> // NOLINT(facebook-unused-include-check)
#include <torch/csrc/stable/tensor.h> // NOLINT(facebook-unused-include-check)
#include <torch/headeronly/core/ScalarType.h> // NOLINT(facebook-unused-include-check)

inline void triton_aot_cu_check(hipError_t err, const char* file, int line) {
  if (err != hipSuccess) {
    const char* err_str;
    (void)hipDrvGetErrorString(err, &err_str);
    throw std::runtime_error(
        std::string(file) + ":" + std::to_string(line) +
        " HIP driver error: " + (err_str ? err_str : "unknown"));
  }
}
#define TRITON_AOT_CU_CHECK(EXPR) triton_aot_cu_check(EXPR, __FILE__, __LINE__)

// The current stream of `device_idx`, which must be the calling thread's
// current device.
// NOLINTNEXTLINE(facebook-hte-NullableReturn): error path throws
inline hipStream_t triton_aot_get_current_stream(int32_t device_idx) {
  void* stream_ptr = nullptr;
  // TODO: No torch::stable op provides the same functionality
  // today. Revisit if torch exposes a proper stable::accelerator stream API.
  // ROCm builds of PyTorch keep the shim's CUDA name.
  if (aoti_torch_get_current_cuda_stream(device_idx, &stream_ptr) != 0) {
    throw std::runtime_error("Failed to get current HIP stream");
  }
  return reinterpret_cast<hipStream_t>(stream_ptr);
}

namespace triton {
namespace aot {

namespace {
int compute_capability() {
  // Cached: AOTT hosts use homogeneous GPUs.
  static int cc = 0;
  if (cc == 0) {
    hipDevice_t device;
    TRITON_AOT_CU_CHECK(hipCtxGetDevice(&device));
    int major, minor;
    TRITON_AOT_CU_CHECK(hipDeviceGetAttribute(
        &major, hipDeviceAttributeComputeCapabilityMajor, device));
    TRITON_AOT_CU_CHECK(hipDeviceGetAttribute(
        &minor, hipDeviceAttributeComputeCapabilityMinor, device));
    cc = major * 10 + minor;
  }
  return cc;
}
} // namespace

namespace {
void enable_large_smem_or_throw(int shared, hipFunction_t func) {
  // HIP: LDS is fully available by default; no opt-in needed.
  // TODO: investigate -- should we still hard-reject ``shared >
  // hipDeviceAttributeMaxSharedMemoryPerBlock`` here, symmetric with the
  // CUDA template? Today AMD AOT-T silently launches and may fail
  // opaquely in hipLaunchKernel.
  (void)shared;
  (void)func;
}
} // namespace

// Hidden for the same reason as the prototypes in kernel.h: one .so per
// forward method, all defining the same `triton::aot::<kernel>` selector, all
// dlopen'd into one predictor process. Only torch_op.cpp calls these, and it
// is compiled into this same .so.
#pragma GCC visibility push(hidden)
// __TRITON_AOT_GENERATE_BEGIN__ KERNEL_SPECS
// __TRITON_AOT_GENERATE_END__ KERNEL_SPECS

// __TRITON_AOT_GENERATE_BEGIN__ SELECTOR
// __TRITON_AOT_GENERATE_END__ SELECTOR
#pragma GCC visibility pop

} // namespace aot
} // namespace triton

// Anchor: keeps the inline `triton_aot_get_current_stream` (and its reference
// to `aoti_torch_get_current_cuda_stream`) from being dead-stripped at
// buck-build time, where KERNEL_SPECS is empty. `weak` dedups the symbol
// across the per-op .so files generated by the runtime template substitution.
extern "C" __attribute__((weak, visibility("default"))) hipStream_t
__triton_aot_anchor_get_stream() {
  return triton_aot_get_current_stream(
      torch::stable::accelerator::getCurrentDeviceIndex());
}
